test("AC14（路径闭合）：活文档里「verifier 写集 = 仅 .rddf/reviews」类陈述必须同时给出记账落点", () => {
  // ── 判据（2026-11-15 升级：从「副词词表」换成「**路径闭合**」）──────────────────────
  // 旧判据只看**副词**（仅 / 只允许 / 只能 / 只有 / 限于）⇒ 实测漏网过一类：
  // `edit 上限=.rddf/reviews`（**无副词**）当时没被本条抓到，是 oracle 在 delegate 工具
  // schema 里人工发现的。新判据 = 「**写集动词/副词** + `.rddf/reviews`」⇒ 该行**必须**
  // 同时给出 `.rddf/state/verifier`（缺 ⇒ 把写集描述窄了）。
  // ⚠ 仍是**枚举式**词表（本仓最后两处之一，与 AC20 的 HIST 并列登记）：未知动词/副词会漏判。
  //   可接受的边界：这类陈述的**必要成分**是「写集动词」本身（不写动词就不构成写集声明）。
  // ⚠ **窗口取舍（6 字符）**：旧判据是 `{0,40}` + `{0,20}` 的宽窗口 —— 实测额外召回的**大多是误报**
  //   （「仅在通过验收后把报告写入 …」这类流程描述）。窄窗口是对**真实故障形态**（紧挨式写集声明）
  //   的定向修复；代价是「动词与路径隔 >6 字符」的松散形态会漏（fail-closed 方向，可接受）。
  // ⚠ 词表里**不写 `edit 上限`**：alternation 中 `上限` 在前 ⇒ 长分支被遮蔽（恒不可达），写了是噪声。
  const CLAIM = /(可写|能写|写集|上限|写入范围|仅|只允许|只能|只有|限于)[^。\n]{0,6}`?\.rddf\/reviews/
  const HIST = /历史|退役|作废|legacy|pre-consolidation|旧路径|旧形态|旧版|收拢前|已收拢/
  const root = path.join(import.meta.dir, "..")
  const scanRoots = ["prompts", "docs", "commands", ".rddf/improvements", ".rddf/roadmap"]
  // ⚠ 同 AC20：`docs/CHANGELOG.md` 是**历史记录**（自述「不描述现状」）且天然逐字引用判据形态
  //   ⇒ 引用即命中判据本身 ⇒ 必须排除，否则本条永远红。
  // ⚠ 未覆盖面（与 AC20 同口径）：`.rddf/plans/**`、未归档 open change 的 `proposal.md`。
  const excluded = ["docs/adr", "docs/CHANGELOG.md"]
  const hits: string[] = []
  const walk = (rel: string) => {
    if (excluded.some((e) => rel === e || rel.startsWith(e + "/"))) return
    const abs = path.join(root, rel)
    for (const entry of readdirSync(abs, { withFileTypes: true })) {
      const next = rel ? `${rel}/${entry.name}` : entry.name
      if (entry.isDirectory()) walk(next)
      else if (entry.name.endsWith(".md")) {
        if (excluded.some((e) => next === e)) continue
        const text = readFileSync(path.join(abs, entry.name), "utf8")
        // 已关闭的 improvement 是历史记录（**与 AC20 共用同一判定** —— 只此一份）
        if (next.startsWith(".rddf/improvements/")
            && isClosedImprovement(text.split("\n").slice(0, 15).join("\n"))) continue
        for (const [i, line] of text.split("\n").entries()) {
          if (HIST.test(line)) continue
          if (!line.includes("verifier")) continue
          if (!CLAIM.test(line)) continue
          // ⚠ 已知边界：本豁免只看「该行是否出现记账落点」。**否定/重定向语境**可洗白
          //   （如「不应写入 .rddf/state/verifier；verifier 写集只有 .rddf/reviews」）——
          //   启发式层面可接受（与 HIST 同属登记在案的边界），不在此闭合。
          if (line.includes(".rddf/state/verifier")) continue
          hits.push(`${next}:${i + 1}: ${line.slice(0, 100)}`)
        }
      }
    }
  }
  for (const r of scanRoots) walk(r)
  expect(hits.join(" | ")).toBe("")
})

test(
  "AC10④：父篇 ADR 的 commit 必须是代码 commit 的祖先或同一 commit（父篇滞后必红）",
  () => {
    // ⚠ **慢执行不判红**：本用例对**真实仓库**跑 3 次 git 子进程（2× `git log -1 --format=%H` 走
    //   pathspec 全历史 + 1× `git merge-base --is-ancestor`）⇒ 常态 0.2–0.3s，但负载尾部实测
    //   5.0–5.1s，会越过 bun 默认的 5000ms 每用例超时 ⇒ **假红**（且文案读起来像「父篇滞后」的
    //   真问题 ⇒ 把排查引向 ADR 提交顺序，而不是机器负载）。
    //   显式超时取负载尾部上界的 ≈4 倍（20s）：慢不再判红，**超时 ≠ 父篇滞后**，~20s 才红只可能是真挂死。
    // 真实仓访问只经 `tests/helpers/real-repo-git.ts` 的两个 InRepo 包装（预算与错误语义在那边）
    const parentSha = lastCommitShaInRepo("docs/adr/ADR-backend-handoff-role-class.md")
    const codeSha = lastCommitShaInRepo("lib/delegate-core.ts")
    if (!parentSha || !codeSha) return // 环境无 git ⇒ 跳过（判据在验收报告里人工核对）
    // is-ancestor 退出码 0 ⇒ 父篇 commit 是代码 commit 的祖先或同一 commit（父篇滞后 ⇒ 退出码 1 ⇒ 红）
    expect(isAncestorInRepo(parentSha, codeSha)).toBe(true)
  },
  // 用例级预算取 helper 的唯一常量：3 次 × 6s = 18s < 20s（见 `tests/helpers/real-repo-git.ts` 注释）
  { timeout: REAL_REPO_GIT_TEST_TIMEOUT_MS },
)

test("AC10④ 的祖先判定（确定性 fixture）：父篇先改 ⇒ 绿 / 代码先改 ⇒ 红 / 同提交 ⇒ 绿", () => {
  // 为什么需要：真实仓的「哪个文件提交更晚」会被**后续提交翻转** ⇒ 只有 fixture 能钉住三态。
  // 两个仓库各造两个提交（线性历史里「两文件最后提交的先后」只能有一个方向）。
  const ADR = "docs/adr/ADR-parent.md"
  const CODE = "lib/code.ts"
  const withRepo = (fn: (repo: string, commit: (files: Record<string, string>) => string) => void) => {
    const repo = mkdtempSync(path.join(tmpdir(), "ac10-ancestor-"))
    const commit = (files: Record<string, string>): string => {
      for (const [rel, text] of Object.entries(files)) {
        mkdirSync(path.dirname(path.join(repo, rel)), { recursive: true })
        writeFileSync(path.join(repo, rel), text)
      }
      gitFixture(repo, "add", "-A")
      gitFixture(repo, "commit", "-q", "-m", "fixture")
      return gitFixture(repo, "rev-parse", "HEAD").trim()
    }
    try {
      gitFixture(repo, "init", "-q", "-b", "main")
      fn(repo, commit)
    } finally {
      rmSync(repo, { recursive: true, force: true })
    }
  }

  // ① 父篇先改、代码后改 ⇒ 父篇 sha 是代码 sha 的祖先 ⇒ 绿
  withRepo((repo, commit) => {
    commit({ [ADR]: "v1\n" })
    commit({ [CODE]: "v1\n" })
    const parentSha = lastCommitSha(repo, ADR)
    const codeSha = lastCommitSha(repo, CODE)
    expect(parentSha).not.toBe("")
    expect(codeSha).not.toBe("")
    expect(isAncestor(repo, parentSha, codeSha)).toBe(true)
  })

  // ② 代码先改、父篇后改 ⇒ 父篇不是代码的祖先 ⇒ isAncestor false ⇒ 真实仓上该形态必红
  withRepo((repo, commit) => {
    commit({ [CODE]: "v2\n" })
    commit({ [ADR]: "v2\n" })
    const codeSha = lastCommitSha(repo, CODE)
    const parentSha = lastCommitSha(repo, ADR)
    expect(codeSha).not.toBe("")
    expect(parentSha).not.toBe("")
    expect(isAncestor(repo, parentSha, codeSha)).toBe(false)
  })

  // ③ 同一个提交同时改两个文件 ⇒ 同一 commit ⇒ 绿
  withRepo((repo, commit) => {
    const same = commit({ [ADR]: "v3\n", [CODE]: "v3\n" })
    expect(lastCommitSha(repo, ADR)).toBe(same)
    expect(lastCommitSha(repo, CODE)).toBe(same)
    expect(isAncestor(repo, same, same)).toBe(true)
  })
})

